import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"系统组成","description":"","frontmatter":{},"headers":[],"relativePath":"zh/intro/components.md","filePath":"zh/intro/components.md","lastUpdated":1791353800000}'),n={name:"zh/intro/components.md"};function i(l,t,d,s,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="系统组成" tabindex="-1">系统组成 <a class="header-anchor" href="#系统组成" aria-label="Permalink to &quot;系统组成&quot;">​</a></h1><p>系统由<strong>六个部分</strong>组成：两个面向内部的管理端、两个面向终端用户的网页端、一个原生移动 App，以及自托管的 Web3 钱包 BTX Wallet。</p><h2 id="各端职责" tabindex="-1">各端职责 <a class="header-anchor" href="#各端职责" aria-label="Permalink to &quot;各端职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端</th><th>谁在用</th><th>主要做什么</th></tr></thead><tbody><tr><td><strong>运营后台</strong></td><td>平台运营、财务、客服</td><td>功能最全的一端。用户管理、实名审核、充值与提现审核、资金流水、币种与交易对管理、玩法开关、站点配置、数据看板</td></tr><tr><td><strong>做市商端</strong></td><td>项目方 / 做市商</td><td>交易委托与成交核对</td></tr><tr><td><strong>用户 PC 端</strong></td><td>终端用户</td><td>网页版交易平台，含完整的行情、现货、合约交易界面与账户中心</td></tr><tr><td><strong>用户移动端 H5</strong></td><td>终端用户</td><td>手机浏览器访问的移动端，功能与 PC 端对齐</td></tr><tr><td><strong>原生双端 App（Android / iOS）</strong></td><td>终端用户</td><td>原生 App，非网页套壳。详见 <a href="/CoinExchange/zh/app/overview">App 介绍</a></td></tr><tr><td><strong>BTX Wallet（Web3 钱包，内测中）</strong></td><td>终端用户</td><td>自托管钱包，链上买卖代币化美股。详见 <a href="/CoinExchange/zh/app/wallet">BTX Wallet</a></td></tr></tbody></table><h2 id="用户端功能分布" tabindex="-1">用户端功能分布 <a class="header-anchor" href="#用户端功能分布" aria-label="Permalink to &quot;用户端功能分布&quot;">​</a></h2><p>用户 PC 端与移动端 H5 面向同一批用户，功能整体对齐：</p><ul><li><strong>行情</strong>：币种列表、K 线图表、实时报价</li><li><strong>交易</strong>：现货、闪兑、秒合约、U 本位合约、TradFi 标的</li><li><strong>资产</strong>：充值、提现、划转、账单流水</li><li><strong>理财</strong>：理财、质押、助力贷、申购</li><li><strong>账户</strong>：登录注册、实名认证、安全设置（登录密码 / 资金密码 / 邮箱 / 谷歌验证）、邀请与推广</li><li><strong>其他</strong>：帮助中心、公告、在线客服、语言切换</li></ul><h2 id="运营后台的模块分布" tabindex="-1">运营后台的模块分布 <a class="header-anchor" href="#运营后台的模块分布" aria-label="Permalink to &quot;运营后台的模块分布&quot;">​</a></h2><ul><li><strong>系统管理</strong>：管理员账号、角色与权限、菜单、字典、公告、帮助中心</li><li><strong>业务管理</strong>：用户、资产、银行卡、实名认证、充值、提现、归集、佣金、资金流水、币种与交易对、地域限制</li><li><strong>交易与玩法</strong>：现货、U 本位合约、秒合约、助力贷、质押、申购、理财、跟单</li><li><strong>配置中心</strong>：站点配置（详见<a href="/CoinExchange/zh/guide/site-config">站点配置</a>）、支付网关、短信与邮件、<a href="/CoinExchange/zh/guide/customer-service">在线客服</a>（Telegram 接待）</li><li><strong>数据看板</strong>：平台运营数据统计</li></ul><h2 id="技术形态" tabindex="-1">技术形态 <a class="header-anchor" href="#技术形态" aria-label="Permalink to &quot;技术形态&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">面向技术评估</p><ul><li>后端：Java（Spring Boot），提供两套服务——面向运营后台的管理服务与面向终端用户的业务服务</li><li>前端：Vue 技术栈，四个独立工程</li><li>移动端：Flutter 原生 App（Android / iOS）</li><li>数据存储：MySQL + Redis</li><li>实时行情：WebSocket 推送</li></ul></div><p>具体的部署环境要求、服务器规格与运维方案，请联系我们获取部署文档。</p>',12)])])}const u=r(n,[["render",i]]);export{p as __pageData,u as default};
